function validate([nums, queries]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => v < 0 || v > 500000)) return 'Each value of nums is between 0 and 5 * 10^5.';
  if (queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 entries.';
  for (const query of queries) {
    if (query.length !== 3) return 'Each query is [l, r, val].';
    const [l, r, val] = query;
    if (l < 0 || l > r || r >= nums.length) return 'Each query needs 0 <= l <= r < nums.length.';
    if (val < 1 || val > 5) return 'Each val is between 1 and 5.';
  }
  return null;
}

