function minZeroArray(nums, queries) {
  const n = nums.length;

  function canZero(k) {
    const diff = new Array(n + 1).fill(0);
    for (let j = 0; j < k; j++) {
      const [left, right, val] = queries[j];
      diff[left] += val;
      diff[right + 1] -= val;
    }
    let cover = 0;
    for (let i = 0; i < n; i++) {
      cover += diff[i];
      if (cover < nums[i]) return false;
    }
    return true;
  }

  let low = 0;
  let high = queries.length;
  if (!canZero(high)) return -1;
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (canZero(mid)) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

