function minZeroArray(nums, queries) {
  // Apply the queries one at a time, always lowering each covered element as far as it can go.
  const need = nums.slice();
  const allZero = () => need.every(v => v === 0);
  if (allZero()) return 0;
  for (let k = 0; k < queries.length; k++) {
    const [l, r, val] = queries[k];
    for (let i = l; i <= r; i++) need[i] = Math.max(0, need[i] - val);
    if (allZero()) return k + 1;
  }
  return -1;
}

