function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 6);
  const q = large ? 2000 : 1 + Math.floor(rand() * 6);
  const queries = [];
  for (let j = 0; j < q; j++) {
    const a = Math.floor(rand() * n);
    const b = Math.floor(rand() * n);
    queries.push([Math.min(a, b), Math.max(a, b), 1 + Math.floor(rand() * 5)]);
  }
  const nums = new Array(n).fill(0);
  if (rand() < 0.25) {
    // Unrelated values: often impossible.
    for (let i = 0; i < n; i++) nums[i] = Math.floor(rand() * (large ? 3000 : 7));
    return [nums, queries];
  }
  // Otherwise keep each value within what a random prefix of the queries covers, so the answer is at most that prefix.
  const k = Math.floor(rand() * (q + 1));
  const diff = new Array(n + 1).fill(0);
  for (let j = 0; j < k; j++) { diff[queries[j][0]] += queries[j][2]; diff[queries[j][1] + 1] -= queries[j][2]; }
  let cover = 0;
  for (let i = 0; i < n; i++) {
    cover += diff[i];
    nums[i] = rand() < 0.3 ? cover : Math.floor(rand() * (cover + 1));
  }
  return [nums, queries];
}
